import React from "react";
import { Outlet } from "react-router-dom";
import Sidebar from "./Sidebar";       // เดี๋ยวสร้างด้านล่าง
import "./App.css";                    // จะใส่สไตล์ layout ที่นี่
import "./sidebar.css";                // สไตล์ของ Sidebar

export default function Layout() {
  return (
    <div className="app-shell">
      <Sidebar />
      <main className="app-main">
        <Outlet />
      </main>
    </div>
  );
}
